// End-to-end generated-header scenarios G1-G5 (LAB-7587): a hand-written Go
// file cannot exempt itself by gaining a `// Code generated … DO NOT EDIT.` header.
import { test } from "node:test";
import assert from "node:assert/strict";
import { baselineJson as bj, check, file, makeRepo } from "./scenario-kit.mjs";

const B = ".github/size-baseline.json";
const GAINED = /::error file=src\/(a|b)\.go::src\/(a|b)\.go gained a `\/\/ Code generated … DO NOT EDIT\.` header it did not have at the merge-base/;
const gen = (n) => `// Code generated by hand. DO NOT EDIT.\n${file("go", n - 1)}`;
const repo = (base, head) => check(makeRepo({ base: { "keep.go": file("go", 3), ...base }, head }));

test("G1: adding the header to an existing hand-written file fails", () => {
  const r = repo({ "src/a.go": file("go", 800) }, { "src/a.go": gen(800) });
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, GAINED);
});

test("G2: adding the header to a baselined file and deleting its entry fails", () => {
  const base = { "src/a.go": file("go", 800), [B]: bj({ "src/a.go": 800 }) };
  const r = repo(base, { "src/a.go": gen(800), [B]: bj({}) });
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, GAINED);
});

test("G3: a new generated file stays exempt", () => {
  const r = repo({}, { "src/a.go": gen(800) });
  assert.equal(r.code, 0, r.out);
});

test("G4: a file already generated at the merge-base stays exempt", () => {
  const r = repo({ "src/a.go": gen(800) }, { "src/a.go": gen(801) });
  assert.equal(r.code, 0, r.out);
});

test("G5: renaming a hand-written file to a generated one fails", () => {
  const r = repo({ "src/a.go": file("go", 800) }, { "src/a.go": null, "src/b.go": gen(800) });
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, GAINED);
  assert.match(r.out, /src\/b\.go gained/);
});
